// Secret 7 self-heal: propose ops.self_heal.proposed need_hitl.
// Forge opens PR; operator merges. n8n does not patch prod.
// Daily notify = Grok Watchdog / Grok chat. Telegram = legacy (no send from this workflow).
// Scorpion register-outcome = legacy optional audit — not required.
// Philanthropy :3002 and OpenClaw :18789 are HOLD — not hard-fail gates.
const body = $json.body || $json;
const correlationId = body.correlationId || body.correlation_id || `self-heal-${Date.now()}`;
const route = body.route || 'unknown';
const statusCode = Number(body.statusCode || body.status_code || 500);
const error = body.error || body.message || 'unknown error';
const stackTrace = body.stackTrace || body.stack || '';
const repo = body.repo || 'n8n-cursor';
const service = body.service || 'hive';
const fixAttempt = Number(body.fix_attempt || body.fixAttempt || 1);
const toolMethod = body.tool_method || body.toolMethod || 'hive_catalog.error_heal';
const businessGoal = body.business_goal || body.businessGoal || 'restore smoke';
const escalate = fixAttempt >= 3;

const text = [
  `SELF-HEAL PROPOSED (Tier 3 merge required)`,
  `cid=${correlationId}`,
  `route=${route} status=${statusCode}`,
  `error=${error}`,
  `repo=${repo} service=${service} attempt=${fixAttempt}`,
  `Forge: branch · patch · test · PR. Operator merges. Do not merge main from n8n.`,
  escalate ? `attempt>=3 → propose hive-creative-pivot (HITL)` : '',
  `Notify: Grok Watchdog / Grok chat (no-send from n8n). Scorpion audit optional. Telegram not sent.`
].filter(Boolean).join('\n');

return [{
  json: {
    text,
    correlationId,
    route,
    statusCode,
    error,
    stackTrace,
    repo,
    service,
    fixAttempt,
    toolMethod,
    businessGoal,
    escalate,
    registerPayload: {
      correlationId,
      jobType: 'ops.self_heal.proposed',
      goal: businessGoal,
      source: 'hive-error-heal',
      status: 'need_hitl',
      registerTo: 'scorpion',
      summary: text,
      metadata: {
        lane: 'hive-os',
        route,
        statusCode: String(statusCode),
        repo,
        service,
        fixAttempt: String(fixAttempt),
        toolMethod,
        scorpion: 'legacy-optional-audit',
        telegramSend: 'omitted',
        notify: 'grok-watchdog-chat',
        philanthropyHold: 'true',
        openclawHold: 'true'
      }
    }
  }
}];

// Alert Outer Heaven — NO SEND.
// Must not Telegram-send. Must not require Scorpion.
// Daily OS notify is Grok Watchdog / Grok chat. This node only attaches an event-bus note.
// Historical Telegram/OH 401 = operator HITL. Do not invent credentials. No new secrets.
// Philanthropy :3002 and OpenClaw :18789 HOLD — do not POST there.
const prev = $input.first().json;
return [{
  json: {
    ...prev,
    alert: {
      dest: 'grok-watchdog-chat',
      channel: 'event-bus-note',
      send: false,
      telegramSend: false,
      scorpionRequired: false,
      summary: prev.text,
      correlationId: prev.correlationId,
      note: 'No-send register-to-Grok/event-bus. Watchdog reads the execution. n8n does not page Telegram or treat Scorpion as OS.'
    }
  }
}];
